"""SI Section 4: exploratory profile comparison.

For each primary aging outcome we compute the model-predicted (age-residualized)
outcome under three pre-specified focal-predictor profiles (favorable / neutral /
unfavorable), with bootstrap 95% CIs, plus each focal predictor's SHAP contribution
under each profile.

Design:
  * Profiles are read from config/profile_specification.yaml (generated by
    analysis/profile_comparison/build_profiles.py); non-focal predictors are held at
    the sample reference (median for numeric, modal category for categorical) taken
    from each model's context.json.
  * Point estimates use the cross-sectional models fitted by fit_models.py (model.json,
    meta.json and context.json under MODELS_DIR). Both they and the MIDUS analytic data
    they are fitted on stay local, so the script needs step profile_models to have run.
  * CIs come from bootstrap-refit with fixed best_params (no re-tuning), residualizing
    y on age within each resample exactly as the manuscript pipeline's fit_final does.

Outputs (output/profile_comparison/): profile_predictions.csv, profile_shap.csv,
and an output log.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np
import pandas as pd
import xgboost as xgb
import yaml
from sklearn.linear_model import LinearRegression

from analysis.core.data_loader import load_master
from analysis.core.output_log import write_output_log
from analysis.core.pub_style import display_name
from analysis.core import artifact_paths as ap

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "output" / "profile_comparison"
CONFIG = ROOT / "config"
# Fitted by fit_models.py (registry step profile_models).
MODELS_DIR = OUT / "models"
TIERS = [1, 2]

# Allostatic load composite
PRIMARY = ["FInoPsy_W1", "btactComp_W1", f"{ap.AL_STEM}_W1"]
LABELS = {"FInoPsy_W1": "Frailty", "btactComp_W1": "Cognition",
          f"{ap.AL_STEM}_W1": "Allostatic load"}
ORDER = ["favorable", "neutral", "unfavorable"]

OUTPUT_LOG_ENTRIES = [
    {"path": "profile_predictions.csv", "kind": "CSV"},
    {"path": "profile_shap.csv", "kind": "CSV"},
]

_CAT_LABELS = yaml.safe_load((CONFIG / "category_labels.yaml").read_text()) or {}
_SPEC = yaml.safe_load((CONFIG / "profile_specification.yaml").read_text())


def profile_for(outcome):
    """Focal predictors + favorable/neutral/unfavorable presets from the spec config."""
    entry = (_SPEC.get("outcomes") or {}).get(outcome)
    if not entry:
        return None
    focal = entry["focal"]
    return {
        "key_fields": [f["name"] for f in focal],
        "presets": {lvl: {f["name"]: f[lvl]["value"] for f in focal} for lvl in ORDER},
    }


def _load_model(outcome):
    model = xgb.XGBRegressor()
    model.load_model(str(MODELS_DIR / outcome / "model.json"))
    return model, _meta(outcome)


def _meta(outcome):
    return json.loads((MODELS_DIR / outcome / "meta.json").read_text())


def _context(outcome):
    return json.loads((MODELS_DIR / outcome / "context.json").read_text())


def _build_row(meta, inputs, ref):
    """One-row profile frame: focal inputs override the reference baseline (median/mode)."""
    features = meta["feature_names"]
    categorical = meta.get("categorical_features", {})
    data, supplied = {}, 0
    for feat in features:
        raw = inputs.get(feat, None)
        if raw is not None and raw != "" and not (isinstance(raw, float) and np.isnan(raw)):
            supplied += 1
        else:
            raw = ref.get(feat, None)
        if feat in categorical:
            cats = categorical[feat]
            val = None if raw is None else str(raw)
            if val not in cats:
                val = None
            data[feat] = pd.Categorical([val], categories=cats)
        else:
            try:
                data[feat] = [float(raw) if raw is not None and raw != "" else np.nan]
            except (TypeError, ValueError):
                data[feat] = [np.nan]
    return pd.DataFrame(data, columns=features), supplied


def _predict_contribs(booster, row, features):
    """(prediction, base, signed SHAP vector) via TreeSHAP on a single row."""
    dmat = xgb.DMatrix(row, enable_categorical=True, feature_names=features)
    contribs = booster.predict(dmat, pred_contribs=True)[0]
    shap = contribs[:-1]
    base = float(contribs[-1])
    return float(shap.sum() + base), base, shap


def _percentile(value, dist):
    if not dist or not dist.get("percentiles"):
        return None
    return float(np.interp(value, dist["percentiles"], dist["percentile_grid"]))


def _resolve_label(feature, raw):
    mapping = _CAT_LABELS.get(feature)
    if mapping is not None:
        try:
            key = int(float(raw))
        except (ValueError, TypeError):
            key = raw
        if key in mapping:
            return str(mapping[key])
    s = str(raw)
    return s[:-2] if s.endswith(".0") else s


def _focal_value_label(feature, raw):
    if isinstance(raw, str):
        return _resolve_label(feature, raw)
    return f"{raw:g}" if isinstance(raw, (int, float)) else str(raw)


def bootstrap(outcome, presets, key_fields, B, seed=42):
    """Bootstrap-refit (fixed best_params) -> profile predictions, fav-unf gap, focal SHAP.
    Residualization mirrors the manuscript pipeline's fit_final (global OLS on age)."""
    X, y, features, age = load_master(outcome, tiers=TIERS, age_residualize=False)
    y = np.asarray(y, dtype=float)
    valid = ~np.isnan(y)
    X = X[valid].reset_index(drop=True)
    y = y[valid]
    age = np.asarray(age, dtype=float)[valid] if age is not None else None

    meta = _meta(outcome)
    bp = dict(meta["best_params"])
    ref = _context(outcome)["reference"]
    rows = {p: _build_row(meta, presets[p], ref)[0] for p in ORDER}
    dmats = {p: xgb.DMatrix(rows[p], enable_categorical=True, feature_names=features) for p in ORDER}
    fidx = {f: features.index(f) for f in key_fields}

    rng = np.random.default_rng(seed)
    n = len(X)
    preds = {p: [] for p in ORDER}
    gaps = []
    fshap = {p: {f: [] for f in key_fields} for p in ORDER}
    for b in range(B):
        idx = rng.integers(0, n, n)
        Xb = X.iloc[idx]
        yb = y[idx].copy()
        if age is not None:
            ab = age[idx]
            av = ~np.isnan(ab)
            if av.sum() > 10:
                reg = LinearRegression().fit(ab[av].reshape(-1, 1), yb[av])
                yb[av] = yb[av] - reg.predict(ab[av].reshape(-1, 1)).ravel()
        model = xgb.XGBRegressor(**bp)
        model.fit(Xb, yb)
        booster = model.get_booster()
        cur = {}
        for p in ORDER:
            contribs = booster.predict(dmats[p], pred_contribs=True)[0]
            shap = contribs[:-1]
            pred = float(shap.sum() + float(contribs[-1]))
            preds[p].append(pred)
            cur[p] = pred
            for f in key_fields:
                fshap[p][f].append(float(shap[fidx[f]]))
        gaps.append(cur["favorable"] - cur["unfavorable"])
        if (b + 1) % 50 == 0:
            print(f"    [{outcome}] bootstrap {b + 1}/{B}")
    return preds, np.array(gaps), fshap


def _ci(a):
    a = np.asarray(a, dtype=float)
    return float(np.percentile(a, 2.5)), float(np.percentile(a, 97.5))


def main(B=200):
    OUT.mkdir(parents=True, exist_ok=True)
    pred_rows, shap_rows = [], []

    for outcome in PRIMARY:
        prof = profile_for(outcome)
        presets, key_fields = prof["presets"], prof["key_fields"]
        focal_types = {fe["name"]: fe["type"] for fe in _SPEC["outcomes"][outcome]["focal"]}
        model, meta = _load_model(outcome)
        booster = model.get_booster()
        features = meta["feature_names"]
        ctx = _context(outcome)
        ref, dist = ctx["reference"], ctx["distribution"]

        # Point estimates (full-sample model)
        point = {}
        for p in ORDER:
            row, _ = _build_row(meta, presets[p], ref)
            pred, base, shap = _predict_contribs(booster, row, features)
            point[p] = {
                "prediction": pred,
                "percentile": _percentile(pred, dist),
                "focal_shap": {f: float(shap[features.index(f)]) for f in key_fields},
            }

        # Bootstrap CIs
        preds, gaps, fshap = bootstrap(outcome, presets, key_fields, B)

        outcome_sd = round(float(dist["sd"]), 4)
        for p in ORDER:
            lo, hi = _ci(preds[p])
            pred_rows.append({
                "outcome": LABELS[outcome], "outcome_key": outcome, "profile": p,
                "prediction": round(point[p]["prediction"], 4),
                "ci_lo": round(lo, 4), "ci_hi": round(hi, 4),
                "percentile": round(point[p]["percentile"], 1),
                "outcome_sd": outcome_sd,
            })
            for f in key_fields:
                slo, shi = _ci(fshap[p][f])
                shap_rows.append({
                    "outcome": LABELS[outcome], "outcome_key": outcome, "profile": p,
                    "feature": f, "label": display_name(f),
                    "var_type": focal_types.get(f, ""),
                    "focal_value": _focal_value_label(f, presets[p].get(f)),
                    "shap": round(point[p]["focal_shap"][f], 4),
                    "shap_ci_lo": round(slo, 4), "shap_ci_hi": round(shi, 4),
                })

        gap_point = point["favorable"]["prediction"] - point["unfavorable"]["prediction"]
        glo, ghi = _ci(gaps)
        pred_rows.append({
            "outcome": LABELS[outcome], "outcome_key": outcome,
            "profile": "favorable_minus_unfavorable",
            "prediction": round(gap_point, 4), "ci_lo": round(glo, 4),
            "ci_hi": round(ghi, 4), "percentile": None, "outcome_sd": outcome_sd,
        })

    pred_df = pd.DataFrame(pred_rows)
    shap_df = pd.DataFrame(shap_rows)
    pred_df.to_csv(OUT / "profile_predictions.csv", index=False)
    shap_df.to_csv(OUT / "profile_shap.csv", index=False)
    log_path = write_output_log(
        OUT,
        "profile_comparison_output_log.md",
        script="analysis/profile_comparison/profile_comparison.py",
        outputs=OUTPUT_LOG_ENTRIES,
        run_args={"bootstrap_refits": B},
    )
    print(f"\nWrote {OUT}/ (Table S16 is built from it by build_supplemental_tables.py)")
    print(f"Output log: {log_path}")
    return 0


if __name__ == "__main__":
    B = int(sys.argv[1]) if len(sys.argv) > 1 else 200
    raise SystemExit(main(B))
